use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Delete\TemplateVariableDeleteUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Batch\TemplateVariableTaskDelete;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class TemplateVariableDeleteController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly SqlTemplate $sql,
    private readonly Runner $runner,
    private readonly TemplateVariableDeleteUsecase $deleteUsecase,
  ) {
  }
  #[OA\Delete(path: "/api/document/template-variable/{uid}", tags: ["Template variable"], description: "Delete the record",
    parameters: [
      new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
    responses: [
      new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVariableApiDTO")),
      new OA\Response(response: 404, description: "Not found"),
    ])
  ]
  public function delete(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Delete Template variable");
    $span = $this->startSpan("Delete Template variable");
    $this->sql->begin();
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $this->deleteUsecase->delete($uid);
      $this->sql->commit();
      return $response->withStatus(204)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $this->sql->close();
;      $span->end();
    }
  }
  public function deleteAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Delete all for query Template variable");
    $span = $this->startSpan("Delete all for query Template variable");
    try {
      $params = $request->getQueryParams();
      $filter = new TemplateVariableFilter(
        uids: isset( $params['uid'] ) ? [$params['uid']] : ( isset($params['uids']) ? explode(',', $params['uids']) : null),
        search: $params['search'] ?? null,
        code: $params['code'] ?? null,
        tenant: isset($params['tenant'])? new TenantRef($params['tenant']): null,
        tenants: isset($params['tenants'])? explode(",", $params['tenants']): null,
      );
      $res = $this->runner->run(TemplateVariableTaskDelete::class, ['filter' => $filter]);
      $encoded = json_encode($res);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function checkDeleteAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check delete all for query Template variable");
    $span = $this->startSpan("Check delete all for query Template variable");
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $info = $this->runner->detail( new TaskKey($uid) );
      if( !$info ) {
        throw new NotFoundException('-');
      }
      $encoded = json_encode($info);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(200)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
